			pacing,
			logger: {
				debug: (fields, message) => {
					host.log("debug", message, fields);
				},
				warn: (fields, message) => {
					host.log("warn", message, fields);
				}
			},
			stepTimeoutMs: input.stepTimeoutMs,
			close: () => Promise.resolve([])
